import{_ as a,o as l,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"貔貅帳單匯入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/07-pixiu-bill-import-guide.md","filePath":"v1/zh-HK/guide/07-pixiu-bill-import-guide.md"}'),r={name:"v1/zh-HK/guide/07-pixiu-bill-import-guide.md"};function e(d,t,n,h,s,c){return l(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="貔貅帳單匯入指南" tabindex="-1">貔貅帳單匯入指南 <a class="header-anchor" href="#貔貅帳單匯入指南" aria-label="Permalink to &quot;貔貅帳單匯入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本指南將指引你如何從 <strong>貔貅記帳</strong> 匯出帳單，並匯入到 <strong>考拉記帳</strong> App。</p><p>考拉記帳目前支援匯入 <strong>貔貅記帳匯出的 CSV 帳單檔</strong>（僅 CSV）。</p><hr><h2 id="📱-第一步-在貔貅記帳中匯出帳單" tabindex="-1">📱 第一步：在貔貅記帳中匯出帳單 <a class="header-anchor" href="#📱-第一步-在貔貅記帳中匯出帳單" aria-label="Permalink to &quot;📱 第一步：在貔貅記帳中匯出帳單&quot;">​</a></h2><p>不同版本的貔貅記帳入口可能略有差異，但思路一致：進入「資料匯出/匯出帳單」，選擇時間範圍與匯出格式後保存檔案。</p><h3 id="步驟-1-進入匯出入口" tabindex="-1">步驟 1：進入匯出入口 <a class="header-anchor" href="#步驟-1-進入匯出入口" aria-label="Permalink to &quot;步驟 1：進入匯出入口&quot;">​</a></h3><ol><li>打開 <strong>貔貅記帳</strong> App</li><li>進入 <strong>我的</strong></li><li>找到 <strong>資料匯出 / 匯出帳單</strong>（名稱可能略有不同）</li></ol><h3 id="步驟-2-選擇匯出時間範圍" tabindex="-1">步驟 2：選擇匯出時間範圍 <a class="header-anchor" href="#步驟-2-選擇匯出時間範圍" aria-label="Permalink to &quot;步驟 2：選擇匯出時間範圍&quot;">​</a></h3><ol><li>選擇要匯出的時間範圍（例如：最近一個月、最近三個月）</li><li>確認後開始匯出</li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建議一次匯出不超過 3 個月，避免檔案過大導致解析變慢</li><li>資料量很大時，可分多次匯出後分批匯入</li></ul></blockquote><h3 id="步驟-3-選擇匯出格式並保存" tabindex="-1">步驟 3：選擇匯出格式並保存 <a class="header-anchor" href="#步驟-3-選擇匯出格式並保存" aria-label="Permalink to &quot;步驟 3：選擇匯出格式並保存&quot;">​</a></h3><ol><li>匯出格式請選 <strong>CSV</strong></li><li>把匯出的 CSV 檔保存到裝置本機（或透過「分享/保存到檔案」）</li><li>記住檔案保存位置，方便後續匯入</li></ol><hr><h2 id="📱-第二步-在考拉記帳中匯入" tabindex="-1">📱 第二步：在考拉記帳中匯入 <a class="header-anchor" href="#📱-第二步-在考拉記帳中匯入" aria-label="Permalink to &quot;📱 第二步：在考拉記帳中匯入&quot;">​</a></h2><h3 id="步驟-1-進入匯入頁面" tabindex="-1">步驟 1：進入匯入頁面 <a class="header-anchor" href="#步驟-1-進入匯入頁面" aria-label="Permalink to &quot;步驟 1：進入匯入頁面&quot;">​</a></h3><ol><li>打開考拉記帳 App</li><li>點擊底部導覽列 <strong>「設定」</strong></li><li>在設定頁找到 <strong>「帳單匯入」</strong></li><li>點擊進入帳單匯入頁</li></ol><h3 id="步驟-2-選擇匯入來源" tabindex="-1">步驟 2：選擇匯入來源 <a class="header-anchor" href="#步驟-2-選擇匯入來源" aria-label="Permalink to &quot;步驟 2：選擇匯入來源&quot;">​</a></h3><ol><li>點擊 <strong>「匯入來源」</strong></li><li>在列表中選擇 <strong>「貔貅記帳」</strong></li></ol><blockquote><p>⚠️ <strong>重要</strong>：必須選擇「貔貅記帳」，否則可能導致格式校驗失敗或欄位解析錯誤。</p></blockquote><h3 id="步驟-3-選擇檔案" tabindex="-1">步驟 3：選擇檔案 <a class="header-anchor" href="#步驟-3-選擇檔案" aria-label="Permalink to &quot;步驟 3：選擇檔案&quot;">​</a></h3><ol><li>點擊 <strong>「檔案路徑」</strong></li><li>選擇貔貅記帳匯出的 <strong>CSV</strong> 檔</li><li>確認檔名已顯示</li></ol><h3 id="步驟-4-關聯帳本" tabindex="-1">步驟 4：關聯帳本 <a class="header-anchor" href="#步驟-4-關聯帳本" aria-label="Permalink to &quot;步驟 4：關聯帳本&quot;">​</a></h3><ol><li>點擊 <strong>「關聯帳本」</strong></li><li>選擇匯入目標帳本</li><li>確認帳本選擇</li></ol><h3 id="步驟-5-解析並預覽" tabindex="-1">步驟 5：解析並預覽 <a class="header-anchor" href="#步驟-5-解析並預覽" aria-label="Permalink to &quot;步驟 5：解析並預覽&quot;">​</a></h3><ol><li>點擊右上角 <strong>「解析」</strong></li><li>解析成功後進入預覽頁</li><li>預覽頁可編輯/刪除單筆，或批量跳過無效記錄</li></ol><h3 id="步驟-6-匯入" tabindex="-1">步驟 6：匯入 <a class="header-anchor" href="#步驟-6-匯入" aria-label="Permalink to &quot;步驟 6：匯入&quot;">​</a></h3><ol><li>預覽確認無誤後點擊 <strong>「匯入」</strong></li><li>等待匯入完成</li></ol><hr><h2 id="📋-貔貅帳單檔案格式說明-csv" tabindex="-1">📋 貔貅帳單檔案格式說明（CSV） <a class="header-anchor" href="#📋-貔貅帳單檔案格式說明-csv" aria-label="Permalink to &quot;📋 貔貅帳單檔案格式說明（CSV）&quot;">​</a></h2><p>考拉記帳對貔貅帳單 CSV 的校驗點：</p><ul><li>第一行必須是表頭</li><li><strong>表頭欄位數必須為 10 欄</strong></li><li>使用英文逗號 <code>,</code> 作為分隔符（CSV 標準）</li></ul><h3 id="欄位定義-按順序" tabindex="-1">欄位定義（按順序） <a class="header-anchor" href="#欄位定義-按順序" aria-label="Permalink to &quot;欄位定義（按順序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>欄序號</th><th>欄位含義</th><th>說明</th></tr></thead><tbody><tr><td>1</td><td>日期</td><td>支援 <code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code>，且年份需 ≥ 2016；否則視為無效日期</td></tr><tr><td>2</td><td>父分類</td><td>用於匹配考拉記帳的收支項目父類名稱</td></tr><tr><td>3</td><td>交易分類</td><td>需包含「支出」或「收入」關鍵字；包含「收入」則按收入匯入，否則按支出匯入</td></tr><tr><td>4</td><td>子分類</td><td>用於匹配考拉記帳的收支項目子類名稱</td></tr><tr><td>5</td><td>流入金額</td><td>收入金額欄（允許帶 <code>-</code>，匯入會自動去除符號）</td></tr><tr><td>6</td><td>流出金額</td><td>支出金額欄（允許帶 <code>-</code>，匯入會自動去除符號）</td></tr><tr><td>7</td><td>幣種代碼</td><td>例如 <code>CNY</code> / <code>USD</code>；為空時使用目標帳本預設幣種</td></tr><tr><td>8</td><td>帳戶</td><td>帳戶名稱（用於匹配；不存在時匯入階段會嘗試建立）</td></tr><tr><td>9</td><td>標籤</td><td>多個標籤以逗號分隔（同時支援中文逗號 <code>，</code>）</td></tr><tr><td>10</td><td>備註</td><td>備註文字</td></tr></tbody></table><h3 id="匯入映射-考拉記帳" tabindex="-1">匯入映射（考拉記帳） <a class="header-anchor" href="#匯入映射-考拉記帳" aria-label="Permalink to &quot;匯入映射（考拉記帳）&quot;">​</a></h3><ul><li>日期 → 帳單日期</li><li>交易分類 → 帳單類型（收入/支出）</li><li>父分類 + 子分類 → 收支項目（匹配不到會在預覽提示不完善）</li><li>流入/流出金額 → 金額（由帳單類型決定取哪一欄）</li><li>帳戶 → 帳戶（按名稱匹配；不存在會建立）</li><li>標籤 → 標籤（按名稱匹配/建立並綁定）</li><li>備註 → 備註</li><li>幣種代碼 → 帳單幣種（按 code 匹配；失敗則用帳本幣種）</li></ul><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><ol><li><strong>不自動去重</strong>：重複匯入同一份檔案會生成重複帳單，請避免多次匯入同一時間段。</li><li><strong>收支項目匹配</strong>：按「父分類 + 子分類」匹配；匹配失敗會提示不完善，需要手動選擇後再匯入。</li><li><strong>帳戶有效性</strong>：帳戶名稱為空或僅符號時，可能被視為無效資料並提示補全。</li><li><strong>檔案編碼</strong>：支援 UTF-8/GBK；如出現亂碼，建議用 UTF-8 重新匯出或轉換後再匯入。</li></ol><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-提示「表頭長度不對」" tabindex="-1">Q1：提示「表頭長度不對」？ <a class="header-anchor" href="#q1-提示「表頭長度不對」" aria-label="Permalink to &quot;Q1：提示「表頭長度不對」？&quot;">​</a></h3><p>請確認匯出的 CSV 第一行表頭為 <strong>10 欄</strong>。常見原因：</p><ol><li>不是貔貅記帳匯出的 CSV，欄位數不一致</li><li>用 Excel/WPS 二次編輯後出現多餘分隔符導致欄位數變化</li><li>另存為 CSV 時選了不相容格式（例如分號分隔）</li></ol><h3 id="q2-匯入後金額不對或為-0" tabindex="-1">Q2：匯入後金額不對或為 0？ <a class="header-anchor" href="#q2-匯入後金額不對或為-0" aria-label="Permalink to &quot;Q2：匯入後金額不對或為 0？&quot;">​</a></h3><p>請確認：</p><ol><li>「交易分類」欄包含「支出/收入」關鍵字（決定取「流入金額」或「流出金額」）</li><li>對應金額欄有值且為數字（帶 <code>-</code> 也可以，會自動去除）</li></ol><h3 id="q3-分類匹配不上怎麼辦" tabindex="-1">Q3：分類匹配不上怎麼辦？ <a class="header-anchor" href="#q3-分類匹配不上怎麼辦" aria-label="Permalink to &quot;Q3：分類匹配不上怎麼辦？&quot;">​</a></h3><p>可在預覽頁進入單筆手動選擇收支項目；或先在考拉記帳建立與匯出檔同名的收支項目後再重新解析。</p><hr><p><strong>最後更新</strong>：2026 年 5 月</p>',52)])])}const b=a(r,[["render",e]]);export{g as __pageData,b as default};
